function shortList(records) {
  // Return the names below the attendance limit
  var result = [];
  for (var i = 0; i < records.length; i++) {
    var rec = records[i];
    if (rec.attendance < 80) {
      result.push(rec.name);
    }
  }
  return result;
}

console.log(shortList([{ name: "Ali", attendance: 72 }, { name: "Sara", attendance: 90 }]));

